1	// Graph-first PM view over the decision-graph API (served by the backend at /ui, same origin).
2	import { layout, STAGE } from "./layout.js";
3	
4	const $ = (sel) => document.querySelector(sel);
5	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
6	const short = (s, n) => (s.length > n ? s.slice(0, n - 1) + "…" : s);
7	
8	let graph = { nodes: [], edges: [] };
9	let view = {}; // derived lookups, rebuilt on every load
10	let selected = null;
11	let lastPos = {}; // layout positions of the current render (drag-to-connect snaps back to them)
12	// Modes that turn graph clicks into picks instead of selection:
13	let draft = null; // {type, inputs: [ids], relation}: the "new node" form is open
14	let linking = null; // {from, to}: connect `from` as a new input of `to`
15	// Focus mode: the graph shows only the chain of focusId (what it's built on + what's built on
16	// it), so it stays readable at any size. Off = the whole graph with the chain highlighted.
17	let focusMode = true;
18	let focusId = null;
19	let showOld = false; // old versions are hidden unless something current still builds on them
20	let drawnSig = ""; // which nodes are drawn: refit the view only when that changes
21	let sideTab = "inbox";
22	
23	const store = {
24	  get: (k) => { try { return localStorage.getItem(k); } catch { return null; } },
25	  set: (k, v) => { try { localStorage.setItem(k, v); } catch { /* storage blocked */ } },
26	};
27	let lastSeen = store.get("lastSeen"); // ISO time of the PM's last "mark as seen"; null = first visit
28	const isBrief = (n) => n.type === "Note" && n.content?.kind === "brief";
29	
30	const COLORS = Object.fromEntries(
31	  Object.keys(STAGE).map((t) => [t, getComputedStyle(document.documentElement).getPropertyValue(`--${t}`).trim()]),
32	);
33	
34	const cy = cytoscape({
35	  container: $("#graph"),
36	  minZoom: 0.2,
37	  maxZoom: 2.5,
38	  style: [
39	    { selector: "node", style: {
40	      shape: "round-rectangle", width: 210, height: 64, "background-color": (n) => COLORS[n.data("type")],
41	      label: "data(label)", "text-wrap": "wrap", "text-max-width": 196, "font-size": 11,
42	      "text-valign": "center", color: "#0f172a", "border-width": 1, "border-color": "#cbd5e1",
43	    } },
44	    { selector: "node.stale", style: { "border-width": 3, "border-style": "dashed", "border-color": "#f97316" } },
45	    { selector: "node.superseded", style: { opacity: 0.45 } },
46	    { selector: "node.approve", style: { "border-width": 4, "border-color": "#16a34a" } },
47	    { selector: "node.reject", style: { "border-width": 4, "border-color": "#dc2626" } },
48	    { selector: "node.postpone", style: { "border-width": 4, "border-color": "#a16207" } },
49	    { selector: "node.awaiting", style: { "border-width": 4, "border-style": "double", "border-color": "#7c3aed" } },
50	    { selector: "node.picked", style: { "border-width": 5, "border-style": "solid", "border-color": "#2563eb" } },
51	    { selector: "node:selected", style: { "overlay-color": "#2563eb", "overlay-opacity": 0.15, "overlay-padding": 6 } },
52	    { selector: "edge", style: {
53	      width: 1.5, "line-color": "#94a3b8", "target-arrow-color": "#94a3b8", "target-arrow-shape": "triangle",
54	      "curve-style": "bezier", "font-size": 9, color: "#64748b", "text-background-color": "#f8fafc",
55	      "text-background-opacity": 1,
56	    } },
57	    { selector: "edge.contradicts", style: { "line-color": "#dc2626", "target-arrow-color": "#dc2626", label: "contradicts" } },
58	    { selector: "edge.supports", style: { "line-color": "#16a34a", "target-arrow-color": "#16a34a", label: "supports" } },
59	    { selector: "edge.scores", style: { "line-style": "dashed", label: "scores" } },
60	    { selector: "edge.version", style: { "line-style": "dotted", "line-color": "#f97316", "target-arrow-color": "#f97316", label: "new version" } },
61	    { selector: ".faded", style: { opacity: 0.12 } },
62	  ],
63	});
64	
65	window.cy = cy; // for debugging in the browser console and for UI tests
66	
67	// ---- API ---------------------------------------------------------------
68	
69	async function api(path, body) {
70	  const resp = await fetch(path, body && {
71	    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
72	  });
73	  const data = await resp.json().catch(() => ({}));
74	  if (!resp.ok) throw new Error(typeof data.detail === "string" ? data.detail : JSON.stringify(data.detail ?? resp.statusText));
75	  return data;
76	}
77	
78	function toast(msg, isError = false) {
79	  const t = $("#toast");
80	  t.textContent = msg;
81	  t.className = isError ? "error" : "";
82	  clearTimeout(toast.timer);
83	  toast.timer = setTimeout(() => { t.textContent = ""; }, isError ? 8000 : 3000);
84	}
85	
86	// ---- data --------------------------------------------------------------
87	
88	async function load() {
89	  const [nodes, edges] = await Promise.all([api("/nodes"), api("/edges")]);
90	  // polling during agent runs calls this every 1.5 s: only redraw when something changed
91	  const sig = nodes.map((n) => n.id + n.status).join() + edges.length;
92	  if (sig === load.sig) return;
93	  load.sig = sig;
94	  graph = { nodes, edges };
95	  view = derive(nodes, edges);
96	  if (lastSeen === null) { // first visit: what's there now counts as seen
97	    lastSeen = nodes.length ? nodes.at(-1).timestamp : new Date(0).toISOString();
98	    store.set("lastSeen", lastSeen);
99	  }
100	  render();
101	}
102	
103	function derive(nodes, edges) {
104	  const byId = Object.fromEntries(nodes.map((n) => [n.id, n]));
105	  const decisionsFor = {}, supersededBy = {}, inputs = {}, dependents = {};
106	  for (const e of edges) {
107	    (inputs[e.from_id] ??= []).push(e);
108	    // decisions show up as the target's verdict, not in its "Used by" list
109	    if (e.relation === "decides") (decisionsFor[e.to_id] ??= []).push(byId[e.from_id]);
110	    else (dependents[e.to_id] ??= []).push(e);
111	  }
112	  for (const n of nodes) if (n.replaces) supersededBy[n.replaces] = n.id;
113	  const brief = nodes.filter((n) => isBrief(n) && !supersededBy[n.id]).at(-1) ?? null;
114	  return { byId, decisionsFor, supersededBy, inputs, dependents, brief };
115	}
116	
117	const latestOf = (id) => { while (view.supersededBy[id]) id = view.supersededBy[id]; return id; };
118	
119	/** Everything id is (transitively) built on. */
120	function upstream(id) {
121	  const seen = new Set();
122	  const todo = [id];
123	  while (todo.length) {
124	    for (const e of view.inputs[todo.pop()] || []) if (!seen.has(e.to_id)) { seen.add(e.to_id); todo.push(e.to_id); }
125	  }
126	  return seen;
127	}
128	
129	/** id's chain: what it's built on, what's built on it, and the other versions of those. */
130	function chainIds(id) {
131	  const chain = new Set([id, ...upstream(id), ...builtOn(id)]);
132	  for (const c of [...chain]) {
133	    for (let v = c; view.supersededBy[v]; v = view.supersededBy[v]) chain.add(view.supersededBy[v]);
134	    // older versions + what still hangs off them: the stale nodes an edit broke belong to its chain
135	    for (let v = view.byId[c]?.replaces; v; v = view.byId[v]?.replaces) {
136	      chain.add(v);
137	      for (const d of builtOn(v)) chain.add(d);
138	    }
139	  }
140	  return chain;
141	}
142	
143	/** For a stale node: the edit upstream that broke it, as "EVD-001 was edited → EVD-005". */
144	function brokenBy(id) {
145	  const edited = [...upstream(id)].find((u) => view.supersededBy[u]);
146	  return edited ? { old: edited, now: latestOf(edited) } : null;
147	}
148	
149	const summary = (n) => {
150	  const c = n.content || {};
151	  if (c.rows) return `${c.file ?? "file"} · ${c.rows.length} rows`;
152	  return String(c.text ?? c.quote ?? c.file ?? c.verdict ?? JSON.stringify(c));
153	};
154	const verdictOf = (id) => (view.decisionsFor[id] || []).at(-1)?.content?.verdict;
155	
156	// ---- graph -------------------------------------------------------------
157	
158	function visibleNodes() {
159	  let ns = graph.nodes.filter((n) => n.type in STAGE && !isBrief(n)); // the brief lives in the brief bar
160	  if (!showOld) { // an old version stays only while something current still builds on it (explains a stale node)
161	    ns = ns.filter((n) => !view.supersededBy[n.id] || n.id === focusId
162	      || (view.dependents[n.id] || []).some((e) => !view.supersededBy[e.from_id]));
163	  }
164	  if (focusId && view.byId[focusId]) {
165	    const chain = chainIds(focusId);
166	    ns = ns.filter((n) => chain.has(n.id));
167	  }
168	  return ns;
169	}
170	
171	function render() {
172	  if (focusMode && selected && view.byId[selected]) focusId = selected;
173	  else if (!draft && !linking) focusId = null;
174	  renderGraph();
175	  $("#start").hidden = graph.nodes.length > 0;
176	  if (!graph.nodes.length) guard(renderStart)();
177	  renderStats();
178	  renderJump();
179	  renderBrief();
180	  renderSide();
181	  if (draft || linking) markPicked(); // an open form must survive redraws (e.g. agent polling)
182	  else if (selected && view.byId[selected]) highlight();
183	  else showHint(false);
184	  renderTimeline();
185	}
186	
187	function renderGraph() {
188	  const drawn = visibleNodes();
189	  const pos = layout(drawn, graph.edges);
190	  lastPos = pos;
191	  const sig = drawn.map((n) => n.id).join();
192	  const changed = sig !== drawnSig; // new nodes (e.g. mid agent run) or a new focus must be in view
193	  drawnSig = sig;
194	  cy.elements().remove();
195	  cy.add(drawn.map((n) => ({
196	    group: "nodes",
197	    data: { id: n.id, type: n.type, label: `${n.id}${n.version > 1 ? ` v${n.version}` : ""}\n${short(summary(n), 70)}` },
198	    position: pos[n.id],
199	    classes: [n.status === "stale" && "stale", view.supersededBy[n.id] && "superseded", verdictOf(n.id),
200	      waitingOn(n) && "awaiting"].filter(Boolean).join(" "),
201	  })));
202	  const isDrawn = (id) => id in pos;
203	  // arrows follow the chain (input -> derived), except "X supports/contradicts Y", which points at Y
204	  const pointsAtInput = (e) => e.relation === "supports" || e.relation === "contradicts";
205	  cy.add(graph.edges.filter((e) => isDrawn(e.from_id) && isDrawn(e.to_id)).map((e, i) => ({
206	    group: "edges",
207	    data: { id: `e${i}`, source: pointsAtInput(e) ? e.from_id : e.to_id, target: pointsAtInput(e) ? e.to_id : e.from_id },
208	    classes: e.relation,
209	  })));
210	  cy.add(drawn.filter((n) => n.replaces && isDrawn(n.replaces)).map((n) => ({
211	    group: "edges", data: { id: `v-${n.id}`, source: n.replaces, target: n.id }, classes: "version",
212	  })));
213	  renderFocusbar(drawn.length);
214	  if (changed) requestAnimationFrame(fitView); // after the page layout settled (first load, focus bar height)
215	}
216	
217	function fitView() {
218	  cy.resize();
219	  cy.fit(undefined, 40);
220	  if (cy.zoom() > 1) { cy.zoom(1); cy.center(); } // a 2-node graph shouldn't fill the screen
221	}
222	
223	function renderFocusbar(count) {
224	  const old = `<label><input type="checkbox" id="showOld" ${showOld ? "checked" : ""}> show old versions</label>`;
225	  $("#focusbar").innerHTML = focusId
226	    ? `<span>Chain of <b>${esc(focusId)}</b>: what it's built on and what's built on it (${count} nodes)</span>
227	       <button type="button" data-focus="off">Show whole graph</button>${old}`
228	    : `<span>Whole graph · ${count} nodes</span>
229	       ${selected ? `<button type="button" data-focus="on">Focus on ${esc(selected)}'s chain</button>`
230	         : `<span>Click a node or an inbox item to see only its chain.</span>`}${old}`;
231	}
232	
233	function renderStats() {
234	  const count = (pred) => graph.nodes.filter(pred).length;
235	  const decided = Object.keys(view.decisionsFor).length;
236	  $("#stats").textContent = [
237	    `${graph.nodes.length} nodes`,
238	    `${count((n) => n.type === "Requirement" && !view.supersededBy[n.id])} requirements`,
239	    `${decided} decided`,
240	    `${count((n) => n.status === "stale" && !view.supersededBy[n.id])} stale`,
241	    `${count((n) => waitingOn(n) === "pm")} questions for you`,
242	    `${count((n) => waitingOn(n) === "agent")} waiting for the agent`,
243	  ].join(" · ");
244	}
245	
246	function nodeOptions(current = null) {
247	  const groups = {};
248	  for (const n of graph.nodes) (groups[n.type] ??= []).push(n);
249	  return `<option value="">—</option>` + Object.entries(groups).map(([type, ns]) =>
250	    `<optgroup label="${esc(type)}">${ns.map((n) =>
251	      `<option value="${esc(n.id)}" ${n.id === current ? "selected" : ""}>${esc(n.id)} — ${esc(short(summary(n), 50))}</option>`,
252	    ).join("")}</optgroup>`).join("");
253	}
254	
255	function renderJump() {
256	  $("#jump").innerHTML = nodeOptions(selected);
257	}
258	
259	// ---- work lists: inbox + requirements ----------------------------------
260	// The PM's loop: inbox -> click an item -> its chain -> act -> next item; empty inbox -> Run agent.
261	
262	function inboxGroups() {
263	  const live = graph.nodes.filter((n) => !view.supersededBy[n.id] && !isBrief(n) && n.type !== "Decision");
264	  const seen = new Date(lastSeen || 0);
265	  const broke = (n) => {
266	    const b = brokenBy(n.id);
267	    return b ? `${esc(b.old)} was edited → ${esc(b.now)}` : "something it is built on changed";
268	  };
269	  return [
270	    { key: "asks", title: "The agent asks you", hint: "Answer so it can continue.",
271	      items: live.filter((n) => waitingOn(n) === "pm") },
272	    { key: "broken", title: "Broken by an edit", hint: "Built on something that changed. The agent redoes them on its next run.",
273	      items: live.filter((n) => n.status === "stale"), why: broke,
274	      action: { label: "Let the agent redo these", run: runAgent, primary: true } },
275	    { key: "decide", title: "Waiting for your decision", hint: "Proposed requirements: approve, reject or postpone.",
276	      items: live.filter((n) => n.type === "Requirement" && n.status !== "stale" && !verdictOf(n.id)) },
277	    { key: "agent", title: "Waiting for the agent", hint: "Your requests; handled first on the next run.",
278	      items: live.filter((n) => waitingOn(n) === "agent"), action: { label: "Run agent", run: runAgent } },
279	    { key: "new", title: "New since your last visit",
280	      items: live.filter((n) => !n.created_by.startsWith("PM:") && new Date(n.timestamp) > seen),
281	      why: (n) => esc(n.rationale ? short(n.rationale, 90) : ""), action: { label: "Mark all as seen", run: markSeen } },
282	  ];
283	}
284	
285	function itemHtml(n, why = "") {
286	  const verdict = verdictOf(n.id);
287	  return `<button type="button" class="item ${n.id === selected ? "current" : ""}" data-goto="${esc(n.id)}">
288	    <span class="head"><span class="pill ${esc(n.type)}">${esc(n.id)}</span>
289	      ${verdict ? `<span class="pill ${esc(verdict)}">${esc(verdict)}</span>` : ""}
290	      ${n.status === "stale" ? `<span class="pill stale">stale</span>` : ""}</span>
291	    <span class="text">${esc(short(summary(n), 110))}</span>
292	    ${why ? `<span class="why">${why}</span>` : ""}</button>`;
293	}
294	
295	const MAX_ITEMS = 8;
296	
297	function renderSide() {
298	  const groups = inboxGroups();
299	  renderSide.actions = Object.fromEntries(groups.filter((g) => g.action).map((g) => [g.key, g.action.run]));
300	  const html = groups.filter((g) => g.items.length).map((g) => `
301	    <section class="group ${g.key}">
302	      <h3><span class="dot"></span>${esc(g.title)} (${g.items.length})</h3>
303	      ${g.hint ? `<p class="hint">${esc(g.hint)}</p>` : ""}
304	      ${g.items.slice(0, MAX_ITEMS).map((n) => itemHtml(n, g.why?.(n))).join("")}
305	      ${g.items.length > MAX_ITEMS ? `<p class="meta">+${g.items.length - MAX_ITEMS} more</p>` : ""}
306	      ${g.action ? `<button type="button" class="group-action ${g.action.primary ? "primary" : ""}" data-group="${g.key}">${esc(g.action.label)}</button>` : ""}
307	    </section>`).join("");
308	  $("#inbox").innerHTML = html || (graph.nodes.length
309	    ? `<p class="hint">Nothing needs you right now.</p>
310	       <button type="button" class="group-action primary" data-group="run">Run the agent to continue</button>`
311	    : `<p class="hint">Start a project in the middle panel.</p>`);
312	  const needsPm = groups.filter((g) => ["asks", "broken", "decide"].includes(g.key)).reduce((s, g) => s + g.items.length, 0);
313	  $("#inboxCount").textContent = needsPm || "";
314	  $("#inboxCount").classList.toggle("hot", needsPm > 0);
315	  renderReqs();
316	}
317	
318	const REQ_ORDER = { undecided: 0, postpone: 1, approve: 2, reject: 3 };
319	
320	function renderReqs() {
321	  const reqs = graph.nodes.filter((n) => n.type === "Requirement" && !view.supersededBy[n.id])
322	    .map((n) => ({ n, v: verdictOf(n.id) || "undecided" }))
323	    .sort((a, b) => (b.n.status === "stale") - (a.n.status === "stale") || REQ_ORDER[a.v] - REQ_ORDER[b.v]);
324	  $("#reqCount").textContent = reqs.length || "";
325	  $("#reqs").innerHTML = reqs.map(({ n, v }) => {
326	    const up = [...upstream(n.id)].map((id) => view.byId[id]);
327	    const evidence = up.filter((u) => u.type === "Evidence").length;
328	    const sources = up.filter((u) => u.type === "Source").length;
329	    return itemHtml(n, `${v === "undecided" ? `<span class="pill none">undecided</span> ` : ""}${evidence} evidence · ${sources} source${sources === 1 ? "" : "s"}`);
330	  }).join("") || `<p class="hint">No requirements yet. The agent proposes them from claims.</p>`;
331	}
332	
333	function setTab(tab) {
334	  sideTab = tab;
335	  for (const b of document.querySelectorAll("[data-tab]")) b.setAttribute("aria-selected", String(b.dataset.tab === tab));
336	  $("#inbox").hidden = tab !== "inbox";
337	  $("#reqs").hidden = tab !== "reqs";
338	}
339	
340	function markSeen() {
341	  lastSeen = graph.nodes.length ? graph.nodes.at(-1).timestamp : new Date().toISOString();
342	  store.set("lastSeen", lastSeen);
343	  renderSide();
344	}
345	
346	// ---- brief + start screen ----------------------------------------------
347	
348	function renderBrief() {
349	  const b = view.brief;
350	  $("#briefbar").innerHTML = !graph.nodes.length ? "" : b
351	    ? `<b>Brief</b><span>${esc(b.content.vehicle ?? "")} · ${esc(b.content.market ?? "")}</span>
352	       <span class="goal">${esc(b.content.text ?? "")}</span>
353	       <button type="button" id="editBrief">Edit brief</button>`
354	    : `<span class="meta">No brief yet: the agent doesn't know your goal.</span>
355	       <button type="button" id="editBrief">Set a brief</button>`;
356	}
357	
358	function openBrief() {
359	  enterMode();
360	  const c = view.brief?.content ?? {};
361	  const opt = (values, cur) => values.map((v) => `<option ${v === cur ? "selected" : ""}>${esc(v)}</option>`).join("");
362	  $("#detail").innerHTML = `
363	    <h2>${view.brief ? "Edit the brief" : "Set a brief"}</h2>
364	    <p class="meta">The agent reads the brief on every run and works towards it.
365	      ${view.brief ? `Saving writes v${view.brief.version + 1} of ${esc(view.brief.id)}.` : ""}</p>
366	    <div class="actions">
367	      <label>Vehicle <select id="briefVehicle">${opt(["BMW 5 Series", "BMW 1 Series", "BMW 7 Series"], c.vehicle)}</select></label>
368	      <label>Market <select id="briefMarket">${opt(["Europe", "China", "United States"], c.market)}</select></label>
369	      <label for="briefText">What should the agent work out?</label>
370	      <textarea id="briefText" rows="4">${esc(c.text ?? "")}</textarea>
371	      <label for="reason">Why (optional)</label>
372	      <textarea id="reason"></textarea>
373	      <div class="row"><button type="button" id="saveBrief" class="primary">Save brief</button>
374	        <button type="button" id="cancelMode">Cancel</button></div>
375	    </div>`;
376	}
377	
378	async function saveBrief() {
379	  const content = { kind: "brief", vehicle: $("#briefVehicle").value, market: $("#briefMarket").value,
380	    text: $("#briefText").value.trim() };
381	  if (!content.text) throw new Error("Write what the agent should work out.");
382	  const rationale = $("#reason").value.trim() || null;
383	  const created = view.brief
384	    ? await api("/edit", { content, target_id: view.brief.id, created_by: pmName(), rationale })
385	    : await api("/nodes", { type: "Note", content, inputs: [], created_by: pmName(), rationale });
386	  toast(`Brief saved (${created.id})`);
387	  showHint();
388	  await load();
389	}
390	
391	async function renderStart() {
392	  if (renderStart.done) return;
393	  renderStart.done = true;
394	  $("#startPm").value = $("#pm").value;
395	  const datasets = await api("/datasets");
396	  $("#startSources").innerHTML = datasets.map((d) => `
397	    <label><input type="checkbox" name="dataset" value="${esc(d.name)}" checked> ${esc(d.name)}
398	      <span class="meta">${d.rows} rows</span></label>`).join("")
399	    + `<p class="meta">Other files: use “Import CSV…” above.</p>`;
400	}
401	
402	async function startProject() {
403	  const name = $("#startPm").value.trim();
404	  if (!name) throw new Error("Enter your PM name: every step you take is recorded under it.");
405	  $("#pm").value = name;
406	  store.set("pmName", name);
407	  const files = [...document.querySelectorAll("#startSources input[name=dataset]:checked")].map((i) => i.value);
408	  if (!files.length) throw new Error("Pick at least one source.");
409	  const text = $("#startGoal").value.trim();
410	  if (!text) throw new Error("Write what the agent should work out.");
411	  const by = `PM:${name}`;
412	  await api("/nodes", { type: "Note", inputs: [], created_by: by, rationale: "project brief from the start screen",
413	    content: { kind: "brief", vehicle: $("#startVehicle").value, market: $("#startMarket").value, text } });
414	  for (const f of files) await api("/import/dataset", { name: f, created_by: by });
