581	/** Everything (transitively) built on id, including PM decisions on those nodes. */
582	function builtOn(id) {
583	  const seen = new Set();
584	  const todo = [id];
585	  while (todo.length) {
586	    const cur = todo.pop();
587	    const next = [...(view.dependents[cur] || []).map((e) => e.from_id), ...(view.decisionsFor[cur] || []).map((d) => d.id)];
588	    for (const d of next) if (!seen.has(d)) { seen.add(d); todo.push(d); }
589	  }
590	  return [...seen];
591	}
