593	/** One line saying what happened, in PM language. */
594	function describe(n) {
595	  const ins = view.inputs[n.id] || [];
596	  const ids = (rel) => ins.filter((e) => !rel || e.relation === rel).map((e) => chip(e.to_id)).join(" ");
597	  const request = n.content?.request;
598	  if (n.type === "Decision") return `<b>${esc(n.content?.verdict ?? "decided")}</b> ${ids()}`;
599	  if (n.replaces) {
600	    const old = view.byId[n.replaces];
601	    const sameContent = old && JSON.stringify(old.content) === JSON.stringify(n.content);
602	    const stale = builtOn(n.replaces).filter((id) => view.byId[id]?.status === "stale");
603	    return `${sameContent ? "connected a new input to" : "edited"} ${chip(n.replaces)} → v${n.version} ${chip(n.id)}`
604	      + (stale.length ? `<div class="why">now stale because of this: ${stale.map((id) => chip(id)).join(" ")}</div>` : "");
605	  }
606	  if (n.type === "Source") return `imported ${chip(n.id)}`;
607	  if (request) return `asked the agent to <b>${esc(REQUESTS[request])}</b> ${ids()} ${chip(n.id)}`;
608	  if (n.type === "Question") return `asked ${n.created_by.startsWith("PM:") ? "the agent" : "the PM"} ${chip(n.id)}${ins.length ? ` about ${ids()}` : ""}`;
609	  if (n.type === "Note" && ins.some((e) => view.byId[e.to_id]?.type === "Question")) return `answered ${ids()} with ${chip(n.id)}`;
610	  if (ins.some((e) => e.relation === "contradicts")) return `recorded counter-evidence ${chip(n.id)} against ${ids("contradicts")}`;
611	  if (n.type === "Score") return `scored ${ids()} → ${chip(n.id)}`;
612	  return `added ${esc(n.type)} ${chip(n.id)}${ins.length ? ` from ${ids()}` : ""}`;
613	}
