617	function renderTimeline() {
618	  if (currentView !== "timeline") return;
619	  const types = [...new Set(graph.nodes.map((n) => n.type))];
620	  const typeSel = $("#trailType");
621	  if (typeSel.options.length !== types.length + 1) {
