629	    chain = new Set([selected, ...(el.nonempty() ? el.predecessors().union(el.successors()).nodes().map((x) => x.id()) : [])]);
630	    for (const id of [...chain]) for (const d of view.decisionsFor[id] || []) chain.add(d.id);
