680	const CREATABLE = ["Source", "Evidence", "Claim", "Assumption", "Requirement", "Question", "Note"];
681	const NO_INPUTS = new Set(["Source", "Question", "Note"]); // backend rule: everything else needs inputs
682	const NEXT = { // what a PM typically builds on a node of this type (right-click menu)
683	  Source: ["Evidence"], Evidence: ["Claim"], Claim: ["Requirement", "Assumption"],
