694	// The agent-loop's handled() rule, mirrored: a PM Question/Note is done once the agent built
695	// on it, or — for "challenge" — once the agent built on its target after it was asked.
696	function pmInputDoneBy(n) {
697	  const agentDeps = (id) => (view.dependents[id] || []).map((e) => view.byId[e.from_id])
698	    .filter((d) => d.created_by.startsWith("agent:"));
699	  const own = agentDeps(n.id)[0];
700	  if (own || n.content?.request !== "challenge") return own?.id;
701	  return (view.inputs[n.id] || []).flatMap((e) => agentDeps(e.to_id))
702	    .find((d) => new Date(d.timestamp) > new Date(n.timestamp))?.id;
703	}
